(function(root){
const id=()=> 'cl-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
const panel=(action='')=>({id:id(),action,image:'',previous:'',texts:[],selectedText:null});
const M={id,panel,create(original=''){return {version:1,id:id(),title:'未命名漫画',original,story:original,stage:0,assets:[],scenes:[],scene:0,selected:0,format:'pages',style:'温暖彩色手绘',lettering:true,isSample:false,generated:[]};},
 valid(d){const str=x=>typeof x==='string',safeId=x=>str(x)&&/^[a-zA-Z0-9_-]+$/.test(x),img=x=>str(x)&&(!x||/^(?:assets\/)?[a-zA-Z0-9_-]+\.(?:png|jpg|jpeg|webp)$/.test(x)||/^data:image\/(?:png|jpeg|webp);base64,[a-zA-Z0-9+/=]+$/.test(x));try{return d.version===1&&safeId(d.id)&&['title','original','story','style'].every(k=>str(d[k]))&&Number.isInteger(d.stage)&&d.stage>=0&&d.stage<=4&&Number.isInteger(d.scene)&&Number.isInteger(d.selected)&&['pages','strip','four','single'].includes(d.format)&&Array.isArray(d.assets)&&d.assets.every(a=>safeId(a.id)&&['kind','name','stable'].every(k=>str(a[k])))&&Array.isArray(d.scenes)&&d.scenes.length<=30&&d.scenes.every(s=>safeId(s.id)&&['name','state','beat'].every(k=>str(s[k]))&&Array.isArray(s.assetIds)&&s.assetIds.every(safeId)&&Array.isArray(s.panels)&&s.panels.length>=1&&s.panels.length<=12&&s.panels.every(p=>safeId(p.id)&&str(p.action)&&img(p.image)&&img(p.previous)&&(!p.sampleImage||img(p.sampleImage))&&Array.isArray(p.texts)&&p.texts.length<=30&&p.texts.every(t=>safeId(t.id)&&['dialogue','thought','caption'].includes(t.type)&&str(t.text)&&str(t.speaker)&&['x','y','w','h','size'].every(k=>Number.isFinite(t[k])&&t[k]>=0&&t[k]<=100)&&['tailX','tailY'].every(k=>t[k]===undefined||Number.isFinite(t[k])&&t[k]>=0&&t[k]<=100))));}catch{return false;}},
 draft(d,mode){const s=d.original.trim();if(!s)return;d.story=mode==='polish'?s.replace(/\s+/g,' ').replace(/([。！？])(?=\S)/g,'$1\n'):mode==='scene'?s+'\n\n【一幕草稿】\n起：交代人物所在之处与眼前愿望。\n承：让一个具体动作推动关系。\n转：加入一次意外回应。\n合：用一个可见的小动作收束。':s+'\n\n【短篇结构草稿】\n第一场：人物带着愿望到来，遭遇一个阻碍。\n第二场：一次选择带来改变，与开场形成呼应。';},
 plan(d){if(d.scenes.length)return;let chunks=d.story.split(/\n\s*\n/).filter(Boolean).flatMap(part=>{const lines=part.match(/[^。！？\n]+[。！？]?/g)||[part];return lines.length>5?Array.from({length:Math.ceil(lines.length/4)},(_,i)=>lines.slice(i*4,i*4+4).join('')):[part];});if(chunks.length>30)chunks=[...chunks.slice(0,29),chunks.slice(29).join('\n')];d.scenes=chunks.map((s,i)=>{const lines=s.match(/[^。！？\n]+[。！？]?/g)||[s];return {id:id(),name:'第'+(i+1)+'场',state:'时间、天气、人物情绪待填写',beat:s,assetIds:[],panels:Array.from({length:4},(_,j)=>panel(lines[j]||['建立环境与愿望','动作推进：请从原文补充','关键变化：请从原文补充','回应与收束：请从原文补充'][j])),generated:false};});},
 extract(d){const kinds={人物:['女孩','男孩','老人','店主','母亲','父亲','小明','小红','小满','周叔','机器人'],场景:['书店','学校','街道','公园','咖啡馆','车站','家里'],道具:['伞','书','信','卡片','纸太阳','自行车']};let added=0;for(const [kind,words] of Object.entries(kinds))for(const name of words){if(d.story.includes(name)&&!d.assets.some(a=>a.name===name)){d.assets.push({id:id(),kind,name,stable:'原文关键词候选，请补充稳定外形与设定。'});added++;}}return added;},
 addPanel(s){if(s.panels.length<12)s.panels.push(panel('新增画面：请填写一个主要可见瞬间'));},
 addText(p,type='dialogue',text='新对白'){const t={id:id(),type,text,speaker:'',x:8,y:8,w:44,h:23,size:26};p.texts.push(t);p.selectedText=t.id;return t;},
 setImage(p,image){p.previous=p.image;p.image=image;},
 layout(n,format){const width=1080,gap=20,margin=36,top=88,cols=format==='strip'||format==='single'?1:2;const cellW=(width-2*margin-(cols-1)*gap)/cols;const rows=Math.ceil(n/cols),cellH=format==='single'?1400:format==='strip'?1320:(1440-top-margin-(rows-1)*gap)/rows;return {width,height:cols===2?1440:top+rows*(cellH+gap)+margin-gap,boxes:Array.from({length:n},(_,i)=>({x:margin+(i%cols)*(cellW+gap),y:top+Math.floor(i/cols)*(cellH+gap),w:cellW,h:cellH}))};}
};if(typeof module!=='undefined')module.exports=M;else root.ComicLabModel=M;
})(typeof window!=='undefined'?window:globalThis);

